//! Which clipboard changes may leave the computer, and echo suppression.

/// Formats set by password managers and similar apps to keep content out of clipboard sync.
/// macOS markers (nspasteboard.org) and Windows formats (clipboard history and cloud clipboard).
pub const SECRET_MARKERS: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "ExcludeClipboardContentFromMonitorProcessing",
    "CanIncludeInClipboardHistory",
    "CanUploadToCloudClipboard",
    "x-kde-passwordManagerHint",
];

/// True when the text may be sent to the phone.
pub fn should_sync(formats: &[String], text: Option<&str>) -> bool {
    let Some(text) = text else { return false };
    !text.is_empty()
        && text.len() <= crate::MAX_TEXT_BYTES
        && !formats
            .iter()
            .any(|format| SECRET_MARKERS.contains(&format.as_str()))
}

/// Remembers the text Rohy wrote itself, so reading it back is not sent again (no echo loop).
/// Platforms without a change counter compare contents instead.
#[derive(Debug, Default)]
pub struct EchoGuard {
    last_seen: Option<String>,
}

impl EchoGuard {
    /// Pass the clipboard content at startup so it is not sent.
    pub fn new(current: Option<String>) -> Self {
        Self { last_seen: current }
    }

    /// Call right after Rohy wrote to the clipboard.
    pub fn mark_written(&mut self, text: &str) {
        self.last_seen = Some(text.to_string());
    }

    /// True when the clipboard now holds something new from another app.
    pub fn is_new(&mut self, text: &str) -> bool {
        if self.last_seen.as_deref() == Some(text) {
            return false;
        }
        self.last_seen = Some(text.to_string());
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn filters_secrets_empty_and_oversized_text() {
        let plain = vec!["text/plain".to_string()];
        assert!(should_sync(&plain, Some("hi")));
        assert!(!should_sync(
            &["CanIncludeInClipboardHistory".to_string()],
            Some("pw")
        ));
        assert!(!should_sync(
            &["x-kde-passwordManagerHint".to_string()],
            Some("pw")
        ));
        assert!(!should_sync(&plain, None));
        assert!(!should_sync(&plain, Some("")));
        assert!(!should_sync(
            &plain,
            Some(&"a".repeat(crate::MAX_TEXT_BYTES + 1))
        ));
    }

    #[test]
    fn echo_guard_ignores_own_writes_and_repeats() {
        let mut guard = EchoGuard::new(Some("initial".into()));
        assert!(!guard.is_new("initial"));
        assert!(guard.is_new("copied"));
        assert!(!guard.is_new("copied"));
        guard.mark_written("from phone");
        assert!(!guard.is_new("from phone"));
        assert!(guard.is_new("next"));
        assert!(EchoGuard::default().is_new("x"));
    }
}
